import{_ as a,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"自然","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-自然.md","filePath":"50-概念资料/dict-自然.md","lastUpdated":1778040484000}'),d={name:"50-概念资料/dict-自然.md"};function r(i,t,h,u,c,n){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="自然" tabindex="-1">自然 <a class="header-anchor" href="#自然" aria-label="Permalink to &quot;自然&quot;">​</a></h1><blockquote><p>传统：道家 | 佛家对应：法尔如是 | 儒家对应：天性</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>自然（英文自=自己，然=如此，&quot;自己如此&quot;）是道家核心概念，也是了空居士修行体系中的重要原则——不加造作、顺其自然、恰到好处。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;人法地，地法天，天法道，道法自然——一切都是自然而然。&quot;</p></blockquote><blockquote><p>&quot;道法自然，不是说前面还有一个&#39;自然&#39;让道去效法，而是道本身就是那个样子——自然而然。&quot;</p></blockquote><blockquote><p>&quot;不要追求境界，境界自然会来。你越是追，它越是跑。&quot;</p></blockquote><blockquote><p>&quot;心平气和就是自然。刻意就是造作，造作就离道远了。&quot;</p></blockquote><h2 id="自然在日常修行中的应用" tabindex="-1">自然在日常修行中的应用 <a class="header-anchor" href="#自然在日常修行中的应用" aria-label="Permalink to &quot;自然在日常修行中的应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>自然</th><th>造作</th></tr></thead><tbody><tr><td>静坐</td><td>自然呼吸，似守非守</td><td>调息，刻意入静</td></tr><tr><td>行善</td><td>帮了就帮，不求回报</td><td>做了好事念念不忘</td></tr><tr><td>生活</td><td>该吃吃，该睡睡</td><td>刻意节食，熬夜修行</td></tr><tr><td>人际</td><td>真诚说话</td><td>刻意讨好或表演</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-无为">无为</a> — 自然就是无为</li><li><a href="/50-概念资料/dict-平常心">平常心</a> — 自然的心理状态</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 自然的实践方法</li><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 人与自然一体的状态</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>做事时心里轻轻松松，不要紧绷</li><li>相信&quot;该来的自然会来&quot;</li><li>不攀缘——不强求、不刻意、不造作</li></ul>',17)])])}const b=a(d,[["render",r]]);export{s as __pageData,b as default};
